(() => {
    const ipc = window.__TAURI_INTERNALS__;
    const callbacks = ipc.callbacks;
    const fetchNative = window.fetch;
    const events = [];
    let armedPath;
    let held;
    function record(event) {
        events.push(event);
        document.dispatchEvent(new Event("picker-native-observation"));
    }
    function observe(transport, command, args, successId, errorId) {
        const allowed = ["open_repo", "close_repo", "get_commit_graph", "prefs_set"];
        if (!allowed.includes(command)) return;
        if (command === "prefs_set" && !["recent_repos", "open_tabs"].includes(args.key)) return;
        const target = command === "prefs_set" ? { key: args.key, value: args.value } : { path: args.path };
        const gateThisReply = command === "open_repo" && args.path === armedPath;
        if (gateThisReply) armedPath = undefined;
        record({ phase: "request", transport, command, ...target });
        for (const [id, outcome] of [[successId, "ok"], [errorId, "error"]]) {
            const nativeContinuation = callbacks.get(id);
            if (typeof nativeContinuation !== "function") throw new Error("No Tauri callback for " + command);
            callbacks.set(id, response => {
                record({ phase: "native-reply", command, outcome, ...target });
                const deliver = () => {
                    record({ phase: "delivered", command, outcome, ...target });
                    nativeContinuation(response);
                };
                if (gateThisReply) held = { outcome, response, deliver };
                else deliver();
            });
        }
    }
    window.fetch = function (resource, init) {
        const url = typeof resource === "string" ? resource : "";
        const match = /^(?:ipc:\/\/localhost\/|https?:\/\/ipc\.localhost\/)([^/?]+)/.exec(url);
        if (match && typeof init?.body === "string") {
            const command = decodeURIComponent(match[1]);
            const headers = new Headers(init.headers);
            observe("custom-protocol", command, JSON.parse(init.body),
                Number(headers.get("Tauri-Callback")), Number(headers.get("Tauri-Error")));
        }
        return fetchNative.call(this, resource, init);
    };
    if (typeof window.ipc?.postMessage === "function") {
        const bridge = window.ipc;
        const postNative = bridge.postMessage;
        const postObserved = function (data) {
            const { cmd, payload, callback, error } = JSON.parse(data);
            observe("postMessage", cmd, payload, callback, error);
            return postNative.call(this, data);
        };
        try { bridge.postMessage = postObserved; } catch {}
    }
    window.pickerNative = {
        arm(path) { armedPath = path; },
        get held() { return held && { outcome: held.outcome, response: held.response }; },
        release() {
            if (!held) throw new Error("No native reply to release");
            const { deliver } = held;
            held = undefined;
            deliver();
        },
        waitFor(predicate) {
            if (events.some(predicate)) return true;
            return new Promise(resolve => {
                function check() {
                    if (!events.some(predicate)) return;
                    document.removeEventListener("picker-native-observation", check);
                    resolve(true);
                }
                document.addEventListener("picker-native-observation", check);
            });
        },
        events,
    };
    return true;
})()
